import{_ as e,o as t,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"11. Data Types and Variables","description":"The Little Book of C — 11. Data Types and Variables","frontmatter":{"title":"11. Data Types and Variables","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Language Basics"],"description":"The Little Book of C — 11. Data Types and Variables","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":11,"sidebarWeight":11,"lang":"en-US","alternateEn":"/posts/c教程/en-US/02-Language Basics/011-Data Types and Variables","alternateZh":"/posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables"},"headers":[],"relativePath":"posts/c教程/en-US/02-Language Basics/011-Data Types and Variables.md","filePath":"posts/c教程/en-US/02-Language Basics/011-Data Types and Variables.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/en-US/02-Language Basics/011-Data Types and Variables.md"};function o(p,a,d,l,r,c){return t(),s("div",null,[...a[0]||(a[0]=[n(`<p>[中文版本](/posts/c教程/zh-CN/02-语言基础/011-Data Types and Variables)</p><p>In C, everything begins with types. A type tells the compiler how much memory to reserve, how to interpret the bits stored there, and what operations are allowed. Understanding types is the foundation of writing safe and efficient C programs, it’s how you speak the computer’s native language precisely.</p><h4 id="tiny-code" tabindex="-1">Tiny Code <a class="header-anchor" href="#tiny-code" aria-label="Permalink to &quot;Tiny Code&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int age = 25;              // integer</span></span>
<span class="line"><span>    float height = 1.75;       // floating-point number</span></span>
<span class="line"><span>    char initial = &#39;A&#39;;        // single character</span></span>
<span class="line"><span>    double weight = 68.4;      // double-precision number</span></span>
<span class="line"><span>    printf(&quot;Age: %d\\n&quot;, age);</span></span>
<span class="line"><span>    printf(&quot;Height: %.2f\\n&quot;, height);</span></span>
<span class="line"><span>    printf(&quot;Initial: %c\\n&quot;, initial);</span></span>
<span class="line"><span>    printf(&quot;Weight: %.1lf\\n&quot;, weight);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>Output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Age: 25</span></span>
<span class="line"><span>Height: 1.75</span></span>
<span class="line"><span>Initial: A</span></span>
<span class="line"><span>Weight: 68.4</span></span></code></pre></div><h4 id="core-built-in-types" tabindex="-1">Core Built-in Types <a class="header-anchor" href="#core-built-in-types" aria-label="Permalink to &quot;Core Built-in Types&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Type</th><th>Size (Typical)</th><th>Description</th><th>Format Specifier</th></tr></thead><tbody><tr><td><code>char</code></td><td>1 byte</td><td>Single character</td><td><code>%c</code></td></tr><tr><td><code>int</code></td><td>4 bytes</td><td>Whole number</td><td><code>%d</code></td></tr><tr><td><code>float</code></td><td>4 bytes</td><td>Decimal number (single precision)</td><td><code>%f</code></td></tr><tr><td><code>double</code></td><td>8 bytes</td><td>Decimal number (double precision)</td><td><code>%lf</code></td></tr><tr><td><code>void</code></td><td>–</td><td>No value or type</td><td>–</td></tr></tbody></table><p>Sizes may vary depending on system and compiler, but the relationships remain consistent.</p><p>You can also control how numbers behave using modifiers:</p><table tabindex="0"><thead><tr><th>Modifier</th><th>Example</th><th>Meaning</th></tr></thead><tbody><tr><td><code>short</code></td><td><code>short int x;</code></td><td>Smaller integer (often 2 bytes)</td></tr><tr><td><code>long</code></td><td><code>long int y;</code></td><td>Larger integer (often 8 bytes)</td></tr><tr><td><code>unsigned</code></td><td><code>unsigned int z;</code></td><td>Only non-negative values</td></tr></tbody></table><p>Example:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unsigned int score = 100;</span></span>
<span class="line"><span>long long big_number = 1234567890123LL;</span></span></code></pre></div><h4 id="declaring-and-initializing-variables" tabindex="-1">Declaring and Initializing Variables <a class="header-anchor" href="#declaring-and-initializing-variables" aria-label="Permalink to &quot;Declaring and Initializing Variables&quot;">​</a></h4><p>A variable is simply a named piece of memory. You declare it by specifying its type and name:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int count;       // declaration</span></span>
<span class="line"><span>count = 5;       // assignment</span></span></code></pre></div><p>Or both together:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int count = 5;   // initialization</span></span></code></pre></div><p>Multiple declarations:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int x = 1, y = 2, z = 3;</span></span></code></pre></div><p>Variables must be declared before you use them, and their type cannot change.</p><h4 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h4><p>C is a statically typed language, meaning every variable’s type is known at compile time. This makes programs faster and safer, because the compiler can:</p><ul><li>Catch type mismatches early</li><li>Optimize memory layout</li><li>Predict storage and alignment</li></ul><p>When you understand data types, you understand how your code maps directly to the machine’s memory.</p><p>C forces you to think carefully about what kind of data you’re working with, a skill that improves every program you write, in any language.</p><h4 id="try-it-yourself" tabindex="-1">Try It Yourself <a class="header-anchor" href="#try-it-yourself" aria-label="Permalink to &quot;Try It Yourself&quot;">​</a></h4><p>Create a program that stores and prints:</p><ul><li>Your age as an<code>int</code></li><li>Your height as a<code>float</code></li><li>Your name’s first letter as a<code>char</code></li></ul><p>Add two integers and print the result:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>int a = 10, b = 20;</span></span>
<span class="line"><span>printf(&quot;Sum: %d\\n&quot;, a + b);</span></span></code></pre></div><p>Try using an<code>unsigned int</code> and print what happens if you assign a negative value.</p><p>Use<code>sizeof()</code> to inspect how big each type is on your system:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;Size of int: %zu bytes\\n&quot;, sizeof(int));</span></span></code></pre></div><p>Every number, character, and pointer in C starts here, in the precise world of types and variables. Once you’re fluent in these, memory layout, structs, and pointers will make perfect sense.</p>`,35)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
